export const PRIEST_RIFT_QUEST_ID = "starter.priest_rift";
export const PRIEST_RIFT_TEMPLATE_ID = "priest_rift_crypt";
export const PRIEST_RIFT_LEVELS = 3;

const PRIEST_RIFT_HOOKS_KEY = Symbol.for("jshack:quests:priestRift");
const REWARD_GOLD = 260;
const BOSS_CANDIDATES = Object.freeze(["dark_acolyte", "wraith", "lich", "skeleton"]);
const SPAWN_OFFSETS = Object.freeze([
  Object.freeze([0, 0]),
  Object.freeze([1, 0]),
  Object.freeze([-1, 0]),
  Object.freeze([0, 1]),
  Object.freeze([0, -1]),
  Object.freeze([1, 1]),
  Object.freeze([1, -1]),
  Object.freeze([-1, 1]),
  Object.freeze([-1, -1]),
  Object.freeze([2, 0]),
  Object.freeze([-2, 0]),
  Object.freeze([0, 2]),
  Object.freeze([0, -2]),
]);

function currentPlayerId(world) {
  for (const [id, ni] of world.query(NamedIdentity)) {
    if (String(ni?.identity || "") === "player") return id;
  }
  return 0;
}

function currentPriestId(world) {
  for (const [id, ni] of world.query(NamedIdentity)) {
    if (String(ni?.identity || "") === "townfolk_priest") return id;
  }
  return 0;
}

function currentDepth(world) {
  for (const [, ds] of world.query(DungeonState)) return Number(ds?.currentDepth || 0) | 0;
  return 0;
}

function currentRiftTemplate(world) {
  for (const [, ds] of world.query(DungeonState)) return String(ds?.activeTemplateId || "");
  return "";
}

function currentDownStairPos(world) {
  for (const [, pos, ni] of world.query(Position, NamedIdentity)) {
    if (String(ni?.identity || "") === "stair_down") return { x: pos.x | 0, y: pos.y | 0 };
  }
  for (const [, ds] of world.query(DungeonState)) {
    if (!Array.isArray(ds?.downStairPositions) || ds.downStairPositions.length <= 0) break;
    const first = ds.downStairPositions[0];
    return { x: Number(first?.x || 0) | 0, y: Number(first?.y || 0) | 0 };
  }
  return null;
}

function findObjectiveEntity(world, role) {
  const wantRole = String(role || "");
  for (const [id, target] of world.query(RunObjectiveTarget)) {
    if (String(target?.questId || "") !== PRIEST_RIFT_QUEST_ID) continue;
    if (String(target?.role || "") !== wantRole) continue;
    return id;
  }
  return 0;
}

function pickBossMonster() {
  for (const id of BOSS_CANDIDATES) {
    const monster = getMonster(id);
    if (monster) return monster;
  }
  return null;
}

function findOpenSpawnPosition(world) {
  const anchor = currentDownStairPos(world);
  if (!anchor) return null;
  for (const [dx, dy] of SPAWN_OFFSETS) {
    const x = (anchor.x | 0) + (dx | 0);
    const y = (anchor.y | 0) + (dy | 0);
    if (!isWalkable(x, y)) continue;
    let blocked = false;
    for (const [, pos] of world.query(Position)) {
      if ((pos.x | 0) === x && (pos.y | 0) === y) { blocked = true; break; }
    }
    if (!blocked) return { x, y };
  }
  return anchor;
}

function createPriestRiftBoss(world, quest) {
  const monster = pickBossMonster();
  if (!monster) return 0;
  const at = findOpenSpawnPosition(world);
  if (!at) return 0;
  const depth = Math.max(1, currentDepth(world));
  const scaledHp = Math.max(
    Number(monster.baseHp || 1) + Math.round(depth * Number(monster.hpPerLevel || 0)),
    Math.round(Number(monster.baseHp || 1) * 1.75),
  );
  const bossId = spawnMonsterEntity(world, {
    x: at.x,
    y: at.y,
    name: "The Thing Behind the Psalm",
    identity: String(monster.id || "wraith"),
    maxHp: scaledHp,
    hp: scaledHp,
    faction: "enemy",
    accuracyDerived: Number(monster.attack || 0) + 2,
    damagePowerDerived: Number(monster.attack || 0) + 2,
    evadeDerived: Number(monster.defense || 0) + 1,
    naturalDamageDice: monster.damageDice,
    sizeClass: monster.sizeClass,
    massKg: monster.massKg,
    resistances: monster.resistances,
    speed: monster.speed,
    creatureType: monster.creatureType,
    learnedSpellIds: Array.isArray(monster.learnedSpellIds) ? monster.learnedSpellIds.slice() : undefined,
    equipment: monster.equipment ? { ...monster.equipment } : null,
    wielding: Array.isArray(monster.wielding) ? monster.wielding.slice() : undefined,
    equipped: Array.isArray(monster.equipped) ? monster.equipped.slice() : undefined,
    inventory: Array.isArray(monster.inventory) ? monster.inventory.slice() : undefined,
    maxMana: Number.isFinite(monster.maxMana) ? Number(monster.maxMana) : undefined,
    manaRegen: Number.isFinite(monster.manaRegen) ? Number(monster.manaRegen) : undefined,
  });
  if (!(bossId > 0)) return 0;
  world.add(bossId, RunObjectiveTarget, { questId: PRIEST_RIFT_QUEST_ID, role: "boss" });
  attachEntityToCurrentFloor(world, bossId);
  const vars = quest.vars?.data || {};
  world.set(quest.id, QuestVars, {
    data: {
      ...vars,
      bossId,
      bossName: "The Thing Behind the Psalm",
    },
  });
  world.emit("spawned", {
    id: bossId,
    at: { x: at.x | 0, y: at.y | 0 },
    kind: "priest-rift-boss",
  });
  return bossId;
}

function createQuestRift(ctx) {
  if (String(ctx.vars?.riftId || "")) return;
  const seed = ((ctx.world.seed >>> 0) ^ ((Number(ctx.bind.player || 0) * 0x9e3779b9) >>> 0) ^ 0x50524945) >>> 0;
  const result = createRift(ctx.world, {
    levels: PRIEST_RIFT_LEVELS,
    seed,
    templateId: PRIEST_RIFT_TEMPLATE_ID,
    questId: PRIEST_RIFT_QUEST_ID,
    idPrefix: "priest",
  });
  if (!result?.ok) return;
  const rec = ctx.world.get(ctx.qid, QuestVars);
  ctx.world.set(ctx.qid, QuestVars, {
    data: {
      ...(rec?.data || {}),
      riftId: result.riftId,
      portalId: result.portalId,
      riftOpened: true,
    },
  });
}

export function ensurePriestRiftQuest(world, opts = {}) {
  const playerId = Number(opts.playerId || currentPlayerId(world) || 0) | 0;
  if (!(playerId > 0)) return 0;
  const existing = findQuestEntity(world, PRIEST_RIFT_QUEST_ID, playerId);
  if (existing > 0) return existing;
  const fetch = getQuestRecord(world, STARTER_PRIEST_FETCH_QUEST_ID, playerId);
  if (opts.allowBeforeFetchComplete !== true && String(fetch?.state?.status || "") !== "complete") return 0;
  const priestId = Number(opts.giverId || currentPriestId(world) || 0) | 0;
  if (!(priestId > 0)) return 0;
  ensureQuestRuntimeEventRoutes(world, ["dialog:accepted", "dialog:reported"]);
  return instantiateQuest(
    world,
    PRIEST_RIFT_QUEST_ID,
    { player: playerId, giver: priestId, target: priestId },
    {
      accepted: false,
      riftOpened: false,
      riftId: "",
      portalId: 0,
      bossKilled: false,
      reported: false,
      bossName: "the thing in the rift",
    },
    { node: "offer", status: "active" },
  );
}

export function canOfferPriestRift(world, playerId) {
  const fetch = getQuestRecord(world, STARTER_PRIEST_FETCH_QUEST_ID, playerId);
  if (String(fetch?.state?.status || "") !== "complete") return false;
  const quest = getQuestRecord(world, PRIEST_RIFT_QUEST_ID, playerId);
  return !!quest && String(quest.state?.status || "active") === "active" && String(quest.state?.node || "") === "offer";
}
/**
 * Normalize authored quest reward choices into one canonical shape.
 *
 * A choice may contain a single item (legacy rewardItemIds/rewardItems) or a
 * package of items. The latter keeps reward balance and presentation in the
 * quest definition instead of scattering grant logic through quest scripts.
 */
export function listQuestRewardOptions(questDef, vars = {}) {
  const authored = Array.isArray(vars?.rewardChoices)
    ? vars.rewardChoices
    : (Array.isArray(questDef?.journal?.rewardChoices) ? questDef.journal.rewardChoices : []);
  if (authored.length > 0) {
    return authored.map((choice, index) => {
      const items = Array.isArray(choice?.items)
        ? choice.items
        : (choice?.itemId ? [{ itemId: choice.itemId, count: choice.count }] : []);
      return {
        id: String(choice?.id || items[0]?.itemId || `choice_${index + 1}`),
        label: String(choice?.label || "").trim(),
        items: items
          .filter((item) => item?.itemId)
          .map((item) => ({
            itemId: String(item.itemId),
            count: Math.max(1, Number(item.count || 1) | 0),
          })),
      };
    }).filter((choice) => choice.items.length > 0);
  }

  const authoredItems = Array.isArray(questDef?.journal?.rewardItems)
    ? questDef.journal.rewardItems.filter((item) => item?.itemId)
    : [];
  const ids = authoredItems.length > 0
    ? authoredItems
    : (Array.isArray(questDef?.journal?.rewardItemIds)
      ? questDef.journal.rewardItemIds.map((itemId) => ({ itemId }))
      : []);
  return ids.map((item, index) => ({
    id: String(item.itemId || `choice_${index + 1}`),
    label: String(item.label || "").trim(),
    items: [{
      itemId: String(item.itemId),
      count: Math.max(1, Number(item.count || vars?.rewardItemCounts?.[item.itemId] || 1) | 0),
    }],
  }));
}

export function listQuestRewardItems(questDef, vars = {}) {
  return listQuestRewardOptions(questDef, vars).flatMap((choice) => choice.items);
}

export function listQuestRewardBonusItems(questDef, vars = {}) {
  const authored = Array.isArray(vars?.rewardBonusItems)
    ? vars.rewardBonusItems
    : (Array.isArray(questDef?.journal?.rewardBonusItems) ? questDef.journal.rewardBonusItems : []);
  return authored.filter((item) => item?.itemId).map((item) => ({
    itemId: String(item.itemId),
    count: Math.max(1, Number(item.count || 1) | 0),
    label: String(item.label || "").trim(),
  }));
}

export function selectedQuestRewardItemIds(questDef, vars, rewardId) {
  const selected = listQuestRewardOptions(questDef, vars)
    .find((choice) => choice.id === String(rewardId || "")
      || choice.items.some((item) => item.itemId === String(rewardId || "")));
  return selected ? selected.items.map((item) => item.itemId) : [];
}

import { QuestState } from "../components/QuestState.js";
import { QuestVars } from "../components/QuestVars.js";
import { QuestLog } from "../components/QuestLog.js";
import { createItemById } from "../utils/itemFactory.js";
import { addToInventory } from "../utils/inventoryFacade.js";
import { listQuestRewardBonusItems, listQuestRewardOptions } from "./rewardOptions.js";

function cloneData(data) {
  if (!data || typeof data !== "object") return {};
  return { ...data };
}

export function setVar(key, valueOrFn) {
  return (ctx) => {
    const rec = ctx.world.get(ctx.qid, QuestVars);
    const data = cloneData(rec?.data);
    data[key] = typeof valueOrFn === "function" ? valueOrFn(ctx) : valueOrFn;
    ctx.world.set(ctx.qid, QuestVars, { data });
  };
}

export function incVar(key, amount = 1) {
  return (ctx) => {
    const rec = ctx.world.get(ctx.qid, QuestVars);
    const data = cloneData(rec?.data);
    const delta = typeof amount === "function" ? Number(amount(ctx) || 0) : Number(amount || 0);
    data[key] = Number(data[key] || 0) + delta;
    ctx.world.set(ctx.qid, QuestVars, { data });
  };
}

export function emit(eventName, payloadOrFn = undefined) {
  return (ctx) => {
    const payload = typeof payloadOrFn === "function" ? payloadOrFn(ctx) : payloadOrFn;
    ctx.world.emit?.(eventName, payload);
  };
}

export function setStatus(status) {
  return (ctx) => {
    const state = ctx.world.get(ctx.qid, QuestState);
    if (!state) return;
    ctx.world.set(ctx.qid, QuestState, {
      ...state,
      status: String(status || state.status || "active"),
    });
  };
}

export function noteError(message) {
  return (ctx) => {
    const log = ctx.world.get(ctx.qid, QuestLog);
    if (!log) return;
    ctx.world.set(ctx.qid, QuestLog, {
      ...log,
      lastError: String(typeof message === "function" ? message(ctx) : message || ""),
    });
  };
}

function rewardOptions(ctx) {
  return listQuestRewardOptions(ctx.def, ctx.vars);
}

export function isSelectedReward(ctx) {
  const rewardId = String(ctx.payload?.rewardId || "");
  return ctx.def?.journal?.rewardChoice === true
    && rewardOptions(ctx).some((option) => option.id === rewardId || option.items.some((item) => item.itemId === rewardId))
    && !ctx.vars?.rewardGranted;
}

export function grantSelectedReward() {
  return (ctx) => {
    const rewardId = String(ctx.payload?.rewardId || "");
    const option = rewardOptions(ctx).find((entry) => entry.id === rewardId || entry.items.some((item) => item.itemId === rewardId));
    if (!option) return false;
    const playerId = Number(ctx.bind.player || 0) | 0;
    const granted = [];
    const itemsToGrant = [...option.items, ...listQuestRewardBonusItems(ctx.def, ctx.vars)];
    for (const item of itemsToGrant) {
      const itemId = createItemById(ctx.world, item.itemId, { count: item.count });
      if (!(itemId > 0) || !addToInventory(ctx.world, playerId, itemId)) {
        if (itemId > 0) {
          try { ctx.world.destroy(itemId); } catch {}
        }
        for (const grantedId of granted) {
          try { ctx.world.destroy(grantedId); } catch {}
        }
        return false;
      }
      granted.push(itemId);
    }
    const gold = Math.max(0, Number(ctx.def?.journal?.rewardGold || ctx.vars?.rewardGold || 0) | 0);
    if (gold > 0) {
      const goldId = createItemById(ctx.world, "gold", { count: gold });
      if (goldId > 0) addToInventory(ctx.world, playerId, goldId);
    }
    const rec = ctx.world.get(ctx.qid, QuestVars);
    ctx.world.set(ctx.qid, QuestVars, {
      data: { ...(rec?.data || {}), rewardChoice: option.id, rewardGranted: true },
    });
    return true;
  };
}
